SPIN = "front"
MAX_RPM = 2000

def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)
    b = bearing_to(enemy.x, enemy.y)
    turn = b * 0.02
    r = (me.x * me.x + me.y * me.y) ** 0.5
    if r > 5.8:
        turn = bearing_to(-me.x, -me.y) * 0.03
    fwd = 1.0
    left = fwd - turn
    right = fwd + turn
    if left > 1:
        left = 1
    if left < -1:
        left = -1
    if right > 1:
        right = 1
    if right < -1:
        right = -1
    return (left, right)

def weapons(me, enemy, arena):
    return [spin(SPIN, MAX_RPM)]

def drive(me, enemy, arena):
    if not me.can_drive:
        return (0.0, 0.0)
    b = bearing_to(enemy.x, enemy.y)
    r = distance_to(0.0, 0.0)
    if r > 5.5:
        ex = enemy.x - me.x
        ey = enemy.y - me.y
        if ex * me.x + ey * me.y > 0.0:
            b = bearing_to(0.0, 0.0)
    t = b / 45.0
    if t < -0.8:
        t = -0.8
    elif t > 0.8:
        t = 0.8
    l = 1.0 - t
    rr = 1.0 + t
    if l < -1.0:
        l = -1.0
    elif l > 1.0:
        l = 1.0
    if rr < -1.0:
        rr = -1.0
    elif rr > 1.0:
        rr = 1.0
    return (l, rr)

def weapons(me, enemy, arena):
    mem = me.memory
    if me.righting or me.airborne:
        return None
    if me.inverted or me.on_side:
        last = mem.get("sr", -1.0)
        if arena.time - last > 0.5:
            mem["sr"] = arena.time
            return [self_right()]
    else:
        mem["sr"] = -1.0
    f = me.weapons.get("front")
    if not f or f.get("health", 0.0) <= 0.0:
        return None
    b = bearing_to(enemy.x, enemy.y)
    rpm = 3500.0
    if abs(b) > 25.0:
        rpm = 1500.0
    if distance_to(0.0, 0.0) > 5.5:
        h = radians(me.heading)
        if me.x * cos(h) + me.y * sin(h) > 0.3:
            rpm = 0.0
    return [spin("front", rpm)]

def drive(me, enemy, arena):
