    fwd = 1.0
    if d < 0.9:
        steer = steer * 0.35
    left = fwd - steer
    right = fwd + steer
    if left > 1:
        left = 1
    if left < -1:
        left = -1
    if right > 1:
        right = 1
    if right < -1:
        right = -1
    return (left, right)

